import{_ as a,o as n,a as c,b as p}from"./app.UgfkfLuP.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API<a npu_parse_enabled=\\"true\\"></a>","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"数据搬运导览","link":"/api/SIMD-API/c_api/data_move_guide/data_move_guide"},{"text":"GM与L1/L0数据搬运","link":"/api/SIMD-API/c_api/data_move_guide/gm_l1_or_l0_data_move"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/data_move_guide/gm_l1_or_l0_data_move.md","filePath":"api/SIMD-API/c_api/data_move_guide/gm_l1_or_l0_data_move.md","outlineHeaders":[{"level":2,"title":"总体说明","slug":"总体说明","link":"#总体说明"},{"level":2,"title":"asc_copy_gm2l1（GM到L1连续或高维切分数据搬运）","slug":"asc_copy_gm2l1（GM到L1连续或高维切分数据搬运）","link":"#asc_copy_gm2l1（GM到L1连续或高维切分数据搬运）"},{"level":2,"title":"asc_copy_gm2l1（GM到L1二维分形矩阵搬运）","slug":"asc_copy_gm2l1（GM到L1二维分形矩阵搬运）","link":"#asc_copy_gm2l1（GM到L1二维分形矩阵搬运）"},{"level":2,"title":"asc_copy_gm2l1_nd2nz（GM到L1随路ND2Nz搬运）","slug":"asc_copy_gm2l1_nd2nz（GM到L1随路ND2Nz搬运）","link":"#asc_copy_gm2l1_nd2nz（GM到L1随路ND2Nz搬运）"},{"level":2,"title":"asc_copy_gm2l1_dn2nz（GM到L1随路DN2Nz搬运）","slug":"asc_copy_gm2l1_dn2nz（GM到L1随路DN2Nz搬运）","link":"#asc_copy_gm2l1_dn2nz（GM到L1随路DN2Nz搬运）"},{"level":2,"title":"asc_copy_gm2l1_align（GM到L1非对齐数据搬运）","slug":"asc_copy_gm2l1_align（GM到L1非对齐数据搬运）","link":"#asc_copy_gm2l1_align（GM到L1非对齐数据搬运）"},{"level":2,"title":"asc_copy_l0c2gm（L0C到GM随路处理搬运）","slug":"asc_copy_l0c2gm（L0C到GM随路处理搬运）","link":"#asc_copy_l0c2gm（L0C到GM随路处理搬运）"},{"level":2,"title":"GM到L0A/L0B的两段搬运","slug":"GM到L0A/L0B的两段搬运","link":"#GM到L0A/L0B的两段搬运"}],"lastUpdated":1791622466000}'),l={name:"api/SIMD-API/c_api/data_move_guide/gm_l1_or_l0_data_move.md"};function _(t,s,e,d,o,i){return n(),c("div",null,[...s[0]||(s[0]=[p(`<div><article class="markdown-body"><h1>GM与L1/L0数据搬运</h1><p>NPU架构版本3510提供GM到L1 Buffer和L0C Buffer到GM两类直达通路。矩阵输入从GM进入L0A Buffer/L0B Buffer时，需要先通过PIPE_MTE2搬到L1 Buffer，再通过PIPE_MTE1装载到L0A Buffer/L0B Buffer；矩阵计算结果可通过PIPE_FIX从L0C Buffer直接搬回GM。NPU架构版本3510不提供GM到L0A Buffer/L0B Buffer或L1 Buffer到GM的直达搬运。</p><h2 id="总体说明">总体说明<a class="header-anchor" href="#总体说明">​</a></h2><table><thead><tr><th>方向</th><th>搬运模式</th><th>接口</th><th>流水</th></tr></thead><tbody><tr><td>GM到L1</td><td>连续搬运，支持通道Padding</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_gm2l1_highdim_split_arch_3510.html">asc_copy_gm2l1</a></td><td>PIPE_MTE2</td></tr><tr><td>GM到L1</td><td>高维切分搬运，支持通道Padding</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_gm2l1_highdim_split_arch_3510.html">asc_copy_gm2l1</a></td><td>PIPE_MTE2</td></tr><tr><td>GM到L1</td><td>二维分形矩阵搬运</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_gm2l1_2d_arch_3510.html">asc_copy_gm2l1</a></td><td>PIPE_MTE2</td></tr><tr><td>GM到L1</td><td>ND到Nz格式转换</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_gm2l1_nd2nz_arch_3510.html">asc_copy_gm2l1_nd2nz</a></td><td>PIPE_MTE2</td></tr><tr><td>GM到L1</td><td>DN到Nz格式转换</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_gm2l1_dn2nz.html">asc_copy_gm2l1_dn2nz</a></td><td>PIPE_MTE2</td></tr><tr><td>GM到L1</td><td>非对齐搬运和Padding</td><td><a href="../cube_datamove/cube_compute_load/asc_copy_gm2l1_align.html">asc_copy_gm2l1_align</a></td><td>PIPE_MTE2</td></tr><tr><td>L0C到GM</td><td>矩阵结果搬出，可组合量化、激活和格式转换</td><td><a href="../cube_datamove/cube_compute_store/asc_copy_l0c2gm_arch_3510.html">asc_copy_l0c2gm</a></td><td>PIPE_FIX</td></tr></tbody></table><h2 id="asc_copy_gm2l1（GM到L1连续或高维切分数据搬运）">asc_copy_gm2l1（GM到L1连续或高维切分数据搬运）<a class="header-anchor" href="#asc_copy_gm2l1（GM到L1连续或高维切分数据搬运）">​</a></h2><p>该接口按照<code>n_burst</code>指定的数据块个数执行搬运。每个数据块包含<code>len_burst</code>个32字节单元，<code>src_stride</code>和<code>dst_stride</code>表示源、目的相邻数据块起始地址之间的距离，单位同样为32字节。只搬运一段连续数据时，可将<code>n_burst</code>设为1，并将两个步长设为0。</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_gm2l1</span><span class="p">(</span><span class="n">__cbuf__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__gm__</span><span class="w"> </span><span class="kt">void</span><span class="o">*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">n_burst</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">len_burst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">asc_channel_pad_mode</span><span class="w"> </span><span class="n">pad_mode</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">src_stride</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dst_stride</span><span class="p">)</span>
</code></pre></div><ul><li><code>dst</code>需要32字节对齐，<code>src</code>需要1字节对齐。</li><li><code>pad_mode</code>用于选择不处理、按通道插入Padding或删除Padding。使用插入Padding模式时，先通过<a href="../cube_datamove/cube_load_aux_config/asc_set_gm2l1_padding.html">asc_set_gm2l1_padding</a>配置填充值；该配置接口不设置Padding模式。</li><li>插入Padding时，每个数据块的<code>len_burst</code>需要按接口要求设置，实际写入L1的数据量可能与GM读取量不同。</li><li>删除Padding时，目的端实际写入量由删除模式决定，计算L1空间时不能只使用源端读取量。</li></ul><h2 id="asc_copy_gm2l1（GM到L1二维分形矩阵搬运）">asc_copy_gm2l1（GM到L1二维分形矩阵搬运）<a class="header-anchor" href="#asc_copy_gm2l1（GM到L1二维分形矩阵搬运）">​</a></h2><p>二维模式从GM矩阵中按行列起始位置和步长选取完整分形，并写入L1。每个分形固定为512字节，搬运过程中不执行格式转换。</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_gm2l1</span><span class="p">(</span><span class="n">__cbuf__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">__gm__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">m_start_position</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">k_start_position</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_stride</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">m_step</span><span class="p">,</span>
<span class="w">                                      </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">k_step</span><span class="p">,</span>
<span class="w">                                      </span><span class="n">asc_load_l2_cache_mode</span><span class="w"> </span><span class="n">l2_cache_mode</span><span class="p">)</span>
</code></pre></div><ul><li><code>m_start_position</code>和<code>m_step</code>以16个元素为单位，<code>k_start_position</code>和<code>k_step</code>以32字节为单位。</li><li><code>dst_stride</code>以512字节为单位，表示目的矩阵列方向相邻分形起始地址的距离。</li><li><code>m_step</code>或<code>k_step</code>为0时不执行搬运；接口不支持只搬运分形内的一部分元素。</li><li>边界不足一个分形时，应在GM侧按后续矩阵计算要求准备完整分形。</li></ul><h2 id="asc_copy_gm2l1_nd2nz（GM到L1随路ND2Nz搬运）">asc_copy_gm2l1_nd2nz（GM到L1随路ND2Nz搬运）<a class="header-anchor" href="#asc_copy_gm2l1_nd2nz（GM到L1随路ND2Nz搬运）">​</a></h2><p>该接口从GM读取ND排布矩阵，在写入L1时转换为Nz分形排布。源矩阵可包含多个ND矩阵，<code>src_d_value</code>描述同一矩阵相邻行起始地址间距，<code>src_nd_matrix_stride</code>描述相邻ND矩阵起始地址间距。</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_gm2l1_nd2nz</span><span class="p">(</span><span class="n">__cbuf__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                            </span><span class="n">__gm__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                            </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">src_d_value</span><span class="p">,</span>
<span class="w">                                            </span><span class="n">asc_load_l2_cache_mode</span><span class="w"> </span><span class="n">l2_cache_mode</span><span class="p">,</span>
<span class="w">                                            </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">n_value</span><span class="p">,</span>
<span class="w">                                            </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">d_value</span><span class="p">,</span>
<span class="w">                                            </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">src_nd_matrix_stride</span><span class="p">,</span>
<span class="w">                                            </span><span class="kt">bool</span><span class="w"> </span><span class="n">enable_small_c0</span><span class="p">)</span>
</code></pre></div><ul><li>调用前通过<a href="../cube_datamove/cube_load_aux_config/asc_set_gm2l1_nz_para.html">asc_set_gm2l1_nz_para</a>设置目的Nz矩阵步长和ND矩阵个数。</li><li><code>src_d_value</code>和<code>src_nd_matrix_stride</code>单位为字节，<code>n_value</code>和<code>d_value</code>单位为元素。</li><li>当每行有效数据不足32字节对齐时，标准模式在目的矩阵补0到32字节边界。</li><li>仅当<code>d_value</code>不大于4时可开启SmallC0模式；此时按4个元素粒度补齐。</li></ul><h2 id="asc_copy_gm2l1_dn2nz（GM到L1随路DN2Nz搬运）">asc_copy_gm2l1_dn2nz（GM到L1随路DN2Nz搬运）<a class="header-anchor" href="#asc_copy_gm2l1_dn2nz（GM到L1随路DN2Nz搬运）">​</a></h2><p>该接口在搬运时把GM中的DN排布转换为L1中的Nz排布，适用于深度方向连续的数据。参数形式与ND2Nz接口相近，但<code>n_value</code>表示DN矩阵列数，<code>d_value</code>表示DN矩阵行数。</p><ul><li>调用前同样通过<code>asc_set_gm2l1_nz_para</code>设置目的Nz矩阵步长和DN矩阵个数。</li><li><code>src_nd_matrix_stride</code>为0且矩阵个数大于1时，表示重复读取第一个DN矩阵。</li><li>SmallC0的开启条件、地址对齐和L1容量要求与接口文档一致。</li></ul><h2 id="asc_copy_gm2l1_align（GM到L1非对齐数据搬运）">asc_copy_gm2l1_align（GM到L1非对齐数据搬运）<a class="header-anchor" href="#asc_copy_gm2l1_align（GM到L1非对齐数据搬运）">​</a></h2><p>该接口支持有效块长不是32字节整数倍的数据，并可在目的L1中执行补齐。高维切分模式通过数据块个数、有效字节数、左右Padding、填充来源、L2 Cache策略和源/目的步长描述搬运。</p><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_gm2l1_align</span><span class="p">(</span><span class="n">__cbuf__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                            </span><span class="n">__gm__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                            </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">burst_count</span><span class="p">,</span>
<span class="w">                                            </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">burst_len</span><span class="p">,</span>
<span class="w">                                            </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">left_padding_count</span><span class="p">,</span>
<span class="w">                                            </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">right_padding_count</span><span class="p">,</span>
<span class="w">                                            </span><span class="kt">bool</span><span class="w"> </span><span class="n">enable_data_select</span><span class="p">,</span>
<span class="w">                                            </span><span class="n">asc_load_l2_cache_mode</span><span class="w"> </span><span class="n">l2_cache_mode</span><span class="p">,</span>
<span class="w">                                            </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">src_stride</span><span class="p">,</span>
<span class="w">                                            </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dst_stride</span><span class="p">)</span>
</code></pre></div><ul><li><strong>Compact模式：</strong> <code>dst_stride</code>等于<code>burst_len</code>，左右Padding为0。多个数据块在L1中紧密排列，仅在整体末尾补齐到32字节边界。</li><li><strong>Normal模式：</strong> <code>dst_stride</code>不等于<code>burst_len</code>且为32字节的整数倍，每个数据块分别补齐。该对齐约束在<code>burst_count</code>为1时仍生效。</li><li><strong>填充值来源：</strong> 左右Padding均为0时，<code>enable_data_select</code>为<code>false</code>表示使用每个数据块的首元素填充，为<code>true</code>表示使用<a href="../cube_datamove/cube_load_aux_config/asc_set_gm2l1_pad.html">asc_set_gm2l1_pad</a>预先配置的常量。<code>enable_data_select</code>为<code>true</code>时，即使左右Padding均为0，也必须先配置填充值。</li><li><strong>左右Padding模式：</strong> <code>left_padding_count</code>或<code>right_padding_count</code>非0时，左、右数量的单位为元素，<code>enable_data_select</code>不生效，硬件强制使用常量填充。此时必须先调用<code>asc_set_gm2l1_pad</code>配置填充值。</li><li><strong>循环填充模式：</strong> 通过<a href="../cube_datamove/cube_load_aux_config/asc_set_gm2l1_loop_size.html">asc_set_gm2l1_loop_size</a>、<a href="../cube_datamove/cube_load_aux_config/asc_set_gm2l1_loop1_stride.html">asc_set_gm2l1_loop1_stride</a>和<a href="../cube_datamove/cube_load_aux_config/asc_set_gm2l1_loop2_stride.html">asc_set_gm2l1_loop2_stride</a>配置两层循环，不能与左右Padding同时开启。</li></ul><p><code>burst_len</code>、<code>src_stride</code>和<code>dst_stride</code>的单位均为字节；<code>src</code>需要1字节对齐，<code>dst</code>需要32字节对齐。循环填充模式的loop1、loop2目的步长也必须32字节对齐，对应循环次数为1时仍生效。目的L1空间需要包含有效数据、左右Padding、补齐到32字节边界的dummy数据，以及<code>dst_stride</code>和loop目的步长产生的最大偏移。</p><h2 id="asc_copy_l0c2gm（L0C到GM随路处理搬运）">asc_copy_l0c2gm（L0C到GM随路处理搬运）<a class="header-anchor" href="#asc_copy_l0c2gm（L0C到GM随路处理搬运）">​</a></h2><p>该接口将Cube计算结果从L0C搬到GM，可在PIPE_FIX中组合以下能力：</p><ul><li>输出Nz排布，或执行Nz2ND、Nz2DN格式转换。</li><li>将<code>int32_t</code>或<code>float</code>结果转换为4位、8位、16位或32位目的类型。</li><li>执行scalar或tensor量化。</li><li>执行Normal、Scalar、Vector或Clip ReLU等激活模式。</li><li>在满足数据类型和布局约束时执行通道拆分。</li><li>通过UnitFlag与矩阵计算建立分形粒度的流水并行。</li></ul><p>调用前根据功能组合配置以下状态：</p><table><thead><tr><th>功能</th><th>配置接口</th></tr></thead><tbody><tr><td>Nz2ND/Nz2DN</td><td><a href="../cube_datamove/cube_store_aux_config/asc_set_l0c_copy_nz_para.html">asc_set_l0c_copy_nz_para</a></td></tr><tr><td>Nz2DN通道参数</td><td><a href="../cube_datamove/cube_store_aux_config/asc_set_l0c_copy_channel_para.html">asc_set_l0c_copy_channel_para</a></td></tr><tr><td>scalar量化</td><td><a href="../cube_datamove/cube_store_aux_config/asc_set_l0c_copy_prequant.html">asc_set_l0c_copy_prequant</a></td></tr><tr><td>tensor量化参数地址</td><td><a href="../cube_datamove/cube_store_aux_config/asc_set_l0c_copy_config.html">asc_set_l0c_copy_config</a></td></tr><tr><td>ReLU/Leaky ReLU参数</td><td><a href="../cube_datamove/cube_store_aux_config/asc_set_l0c_copy_relu_alpha.html">asc_set_l0c_copy_relu_alpha</a>、<a href="../cube_datamove/cube_store_aux_config/asc_set_l0c_copy_lrelu_alpha.html">asc_set_l0c_copy_lrelu_alpha</a></td></tr></tbody></table><p><code>src</code>需要64字节对齐，<code>dst</code>需要1字节对齐。<code>n_size</code>、<code>m_size</code>、<code>dst_stride</code>和源、目的数据类型必须与格式转换、量化及激活组合匹配；目的GM空间应按转换后的数据类型和排布计算。</p><h2 id="GM到L0A/L0B的两段搬运">GM到L0A/L0B的两段搬运<a class="header-anchor" href="#GM到L0A/L0B的两段搬运">​</a></h2><p>NPU架构版本3510的矩阵输入需要按以下顺序准备：</p><ol><li>使用本章GM到L1接口把输入数据或分形搬到L1。</li><li>在PIPE_MTE2与PIPE_MTE1之间建立数据依赖。</li><li>使用<a href="l1_l0_data_move.html">L1与L0数据搬运</a>中的二维、三维、转置或MX接口把L1数据装载到L0A/L0B。</li><li>在PIPE_MTE1与PIPE_M之间建立依赖后发起矩阵计算。</li></ol><p>两段搬运的步长单位不同。GM到L1高维切分以32字节描述块长和起始地址间距，L1到L0二维搬运则以16个元素、32字节和512字节分形混合描述矩阵位置，不能直接复用参数。</p></article></div>`,1)])])}const g=a(l,[["render",_]]);export{h as __pageData,g as default};
